package br.com.sergio.gestaopedidos.service;
import br.com.sergio.gestaopedidos.dto.estoque.*;import br.com.sergio.gestaopedidos.entity.*;import br.com.sergio.gestaopedidos.enums.*;import br.com.sergio.gestaopedidos.exception.*;import br.com.sergio.gestaopedidos.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.util.*;
@Service@RequiredArgsConstructor@Transactional public class EstoqueService{
 private final SaldoEstoqueRepository saldos;private final MovimentacaoEstoqueRepository movimentos;private final InsumoService insumos;private final ProdutoService produtos;
 public void processarCompra(Compra c){if(c.getStatus()==StatusCompra.ESTORNADA)return;for(ItemCompra i:c.getItens()){Ref r=ref(i);if((c.getTipoCompra()==TipoCompra.INSUMO)!=(r.tipo==TipoItemEstoque.INSUMO))throw new BusinessException("Item incompatível com o tipo da compra.");if(!movimentos.existsByItemCompraIdAndTipo(i.getId(),TipoMovimentacaoEstoque.ENTRADA_COMPRA))entrada(r,i.getQuantidade(),i.getValorTotalItem(),i.getCustoUnitario(),TipoMovimentacaoEstoque.ENTRADA_COMPRA,c.getDataCompra().atStartOfDay(),"Compra #"+c.getId(),i,null,i.getNomeHistorico(),i.getUnidadeHistorica());}}
 public void registrarEntradaManual(EntradaEstoqueRequest x){Ref r=ref(x.getTipoItem(),x.getReferenciaId(),true);BigDecimal q=qtd(x.getQuantidade(),r.unidade),v=positivo(x.getValorTotal());entrada(r,q,v,v.divide(q,6,RoundingMode.HALF_UP),TipoMovimentacaoEstoque.ENTRADA_AJUSTE,x.getDataMovimentacao(),texto(x.getObservacao()),null,null,r.nome,r.unidade);}
 public void registrarSaidaManual(SaidaEstoqueRequest x){if(!Set.of(TipoMovimentacaoEstoque.SAIDA_CONSUMO_MANUAL,TipoMovimentacaoEstoque.SAIDA_PERDA,TipoMovimentacaoEstoque.SAIDA_AJUSTE).contains(x.getTipo()))throw new BusinessException("Tipo de saída inválido.");Ref r=ref(x.getTipoItem(),x.getReferenciaId(),true);BigDecimal q=qtd(x.getQuantidade(),r.unidade);SaldoEstoque s=saldo(r);if(s.getQuantidadeAtual().compareTo(q)<0)throw new BusinessException("Estoque insuficiente. Disponível: "+s.getQuantidadeAtual().stripTrailingZeros().toPlainString()+" "+r.unidade.getSimbolo()+".");BigDecimal cu=s.getCustoMedioAtual(),v=q.multiply(cu).setScale(2,RoundingMode.HALF_UP);movimentos.save(mov(r,x.getDataMovimentacao(),x.getTipo(),q,v,cu,texto(x.getObservacao()),null,null,r.nome,r.unidade));s.setQuantidadeAtual(s.getQuantidadeAtual().subtract(q).setScale(3));s.setValorTotalEstoque(s.getValorTotalEstoque().subtract(v).max(BigDecimal.ZERO).setScale(2));if(s.getQuantidadeAtual().signum()==0){s.setCustoMedioAtual(zero6());s.setValorTotalEstoque(zero2());}saldos.save(s);}
 public void estornarCompra(Compra c){if(c.getStatus()==StatusCompra.ESTORNADA)throw new BusinessException("Esta compra já foi estornada.");List<MovimentacaoEstoque> os=movimentos.findByItemCompraCompraIdAndTipoOrderByIdAsc(c.getId(),TipoMovimentacaoEstoque.ENTRADA_COMPRA);if(os.isEmpty())throw new BusinessException("A compra ainda não possui entradas de estoque.");for(var o:os){Ref r=ref(o);SaldoEstoque s=saldo(r);if(s.getQuantidadeAtual().compareTo(o.getQuantidade())<0||s.getValorTotalEstoque().compareTo(o.getValorTotal())<0)throw new BusinessException("Não é possível estornar: o estoque atual não comporta a reversão desta compra.");movimentos.save(mov(r,LocalDateTime.now(),TipoMovimentacaoEstoque.ESTORNO_ENTRADA,o.getQuantidade(),o.getValorTotal(),o.getCustoUnitario(),"Estorno da compra #"+c.getId(),o.getItemCompra(),o,o.getNomeHistorico(),o.getUnidadeHistorica()));s.setQuantidadeAtual(s.getQuantidadeAtual().subtract(o.getQuantidade()).setScale(3));s.setValorTotalEstoque(s.getValorTotalEstoque().subtract(o.getValorTotal()).setScale(2));medio(s);saldos.save(s);}c.setStatus(StatusCompra.ESTORNADA);}
 public boolean compraMovimentada(Long id){return!movimentos.findByItemCompraCompraIdAndTipoOrderByIdAsc(id,TipoMovimentacaoEstoque.ENTRADA_COMPRA).isEmpty();}
 @Transactional(readOnly=true)public Page<SaldoEstoqueResponse> listar(String nome,TipoItemEstoque cat,String situacao,Boolean ativo,Pageable p){return saldos.listar(limpar(nome),cat==null?"":cat.name(),limpar(situacao),ativo,p).map(this::map);}
 @Transactional(readOnly=true)public EstoqueIndicadoresResponse indicadores(){BigDecimal a=dinheiro(saldos.somarValor(TipoItemEstoque.INSUMO)),b=dinheiro(saldos.somarValor(TipoItemEstoque.PRODUTO_REVENDA));return EstoqueIndicadoresResponse.builder().itensComSaldo(saldos.contarComSaldo()).abaixoDoMinimo(saldos.listar("","","BAIXO",null,PageRequest.of(0,1)).getTotalElements()).valorInsumos(a).valorRevenda(b).valorTotal(a.add(b)).build();}
 @Transactional(readOnly=true)public Page<MovimentacaoEstoqueResponse> movimentacoes(LocalDate ini,LocalDate fim,TipoItemEstoque cat,Long ref,TipoMovimentacaoEstoque tipo,Long compra,Pageable p){return movimentos.listar(ini==null?null:ini.atStartOfDay(),fim==null?null:fim.plusDays(1).atStartOfDay().minusNanos(1),cat,ref,tipo,compra,p).map(this::map);}
 @Transactional(readOnly=true)public DetalhesEstoqueResponse detalhes(TipoItemEstoque tipo,Long id){Ref r=ref(tipo,id,false);SaldoEstoque s=saldos.buscarSaldo(tipo,id).orElse(novo(r));return DetalhesEstoqueResponse.builder().estoque(montar(r,s.getQuantidadeAtual(),s.getCustoMedioAtual(),s.getValorTotalEstoque(),s.getAtualizadoEm())).movimentacoes(movimentos.ultimas(tipo,id,PageRequest.of(0,20)).stream().map(this::map).toList()).build();}
 private void entrada(Ref r,BigDecimal q,BigDecimal v,BigDecimal cu,TipoMovimentacaoEstoque tipo,LocalDateTime data,String obs,ItemCompra item,MovimentacaoEstoque origem,String nome,UnidadeMedida un){q=qtd(q,un);v=dinheiro(v);SaldoEstoque s=saldo(r);BigDecimal nq=s.getQuantidadeAtual().add(q).setScale(3),nv=s.getValorTotalEstoque().add(v).setScale(2);s.setQuantidadeAtual(nq);s.setValorTotalEstoque(nv);s.setCustoMedioAtual(nv.divide(nq,6,RoundingMode.HALF_UP));movimentos.save(mov(r,data,tipo,q,v,cu,obs,item,origem,nome,un));saldos.save(s);}
 private SaldoEstoque saldo(Ref r){if(r.tipo==TipoItemEstoque.INSUMO)saldos.bloquearInsumo(r.id).orElseThrow(()->new ResourceNotFoundException("Insumo não encontrado."));else saldos.bloquearProduto(r.id).orElseThrow(()->new ResourceNotFoundException("Produto não encontrado."));return saldos.bloquearSaldo(r.tipo,r.id).orElseGet(()->novo(r));}private SaldoEstoque novo(Ref r){return SaldoEstoque.builder().tipoItem(r.tipo).insumo(r.insumo).produto(r.produto).build();}
 private Ref ref(TipoItemEstoque t,Long id,boolean ativo){if(t==null||id==null)throw new BusinessException("Selecione o tipo e o item.");if(t==TipoItemEstoque.INSUMO){Insumo i=insumos.buscarEntidade(id);if(ativo&&!Boolean.TRUE.equals(i.getAtivo()))throw new BusinessException("Este insumo não está disponível para novas movimentações.");return new Ref(t,id,i,null,i.getNome(),i.getUnidadeMedida(),i.getAtivo(),i.getEstoqueMinimo());}Produto p=produtos.buscarEntidadePorId(id);if(p.getTipoProduto()!=TipoProduto.REVENDA)throw new BusinessException("Somente produtos de revenda podem possuir estoque.");if(ativo&&!Boolean.TRUE.equals(p.getAtivo()))throw new BusinessException("Este produto não está disponível para novas movimentações.");return new Ref(t,id,null,p,p.getNome(),p.getUnidadeVenda()==UnidadeVenda.UNIDADE?UnidadeMedida.UNIDADE:UnidadeMedida.QUILOGRAMA,p.getAtivo(),p.getEstoqueMinimo());}
 private Ref ref(ItemCompra i){if(i.getInsumo()!=null&&i.getProduto()==null)return new Ref(TipoItemEstoque.INSUMO,i.getInsumo().getId(),i.getInsumo(),null,i.getNomeHistorico(),i.getUnidadeHistorica(),i.getInsumo().getAtivo(),i.getInsumo().getEstoqueMinimo());if(i.getProduto()!=null&&i.getInsumo()==null&&i.getProduto().getTipoProduto()==TipoProduto.REVENDA)return new Ref(TipoItemEstoque.PRODUTO_REVENDA,i.getProduto().getId(),null,i.getProduto(),i.getNomeHistorico(),i.getUnidadeHistorica(),i.getProduto().getAtivo(),i.getProduto().getEstoqueMinimo());throw new BusinessException("Referência de estoque inválida.");}private Ref ref(MovimentacaoEstoque m){return new Ref(m.getTipoItem(),m.getInsumo()!=null?m.getInsumo().getId():m.getProduto().getId(),m.getInsumo(),m.getProduto(),m.getNomeHistorico(),m.getUnidadeHistorica(),true,BigDecimal.ZERO);}
 private MovimentacaoEstoque mov(Ref r,LocalDateTime d,TipoMovimentacaoEstoque t,BigDecimal q,BigDecimal v,BigDecimal c,String obs,ItemCompra item,MovimentacaoEstoque origem,String nome,UnidadeMedida un){return MovimentacaoEstoque.builder().tipoItem(r.tipo).insumo(r.insumo).produto(r.produto).nomeHistorico(nome).dataMovimentacao(d==null?LocalDateTime.now():d).tipo(t).quantidade(q).unidadeHistorica(un).valorTotal(v).custoUnitario(c.setScale(6,RoundingMode.HALF_UP)).observacao(obs).itemCompra(item).movimentacaoOrigem(origem).build();}
 private SaldoEstoqueResponse map(SaldoEstoqueRepository.Visao v){Ref r=new Ref(TipoItemEstoque.valueOf(v.getTipoItem()),v.getReferenciaId(),null,null,v.getItemNome(),UnidadeMedida.valueOf(v.getUnidade()),v.getAtivo(),v.getEstoqueMinimo());return montar(r,v.getQuantidadeAtual(),v.getCustoMedioAtual(),v.getValorTotalEstoque(),v.getAtualizadoEm());}private SaldoEstoqueResponse montar(Ref r,BigDecimal q,BigDecimal c,BigDecimal v,LocalDateTime u){q=q==null?BigDecimal.ZERO:q;BigDecimal min=r.minimo==null?BigDecimal.ZERO:r.minimo;boolean baixo=min.signum()>0&&q.compareTo(min)<=0;String sit=q.signum()==0?"Sem estoque":baixo?"Estoque baixo":min.signum()==0?"Sem mínimo configurado":"Normal";return SaldoEstoqueResponse.builder().tipoItem(r.tipo).referenciaId(r.id).nome(r.nome).unidade(r.unidade).ativo(r.ativo).estoqueAtual(q).estoqueMinimo(min).abaixoDoMinimo(baixo).situacao(sit).custoMedioAtual(c==null?zero6():c).valorEstimadoEstoque(v==null?zero2():v).ultimaMovimentacao(u).build();}
 private MovimentacaoEstoqueResponse map(MovimentacaoEstoque m){Long id=m.getInsumo()!=null?m.getInsumo().getId():m.getProduto().getId();String o=m.getMovimentacaoOrigem()!=null?"Estorno #"+m.getMovimentacaoOrigem().getId():m.getItemCompra()!=null?"Compra #"+m.getItemCompra().getCompra().getId():m.getTipo().getDescricao();return MovimentacaoEstoqueResponse.builder().id(m.getId()).tipoItem(m.getTipoItem()).referenciaId(id).nomeHistorico(m.getNomeHistorico()).dataMovimentacao(m.getDataMovimentacao()).tipo(m.getTipo()).quantidade(m.getQuantidade()).unidadeHistorica(m.getUnidadeHistorica()).valorTotal(m.getValorTotal()).custoUnitario(m.getCustoUnitario()).origem(o).observacao(m.getObservacao()).build();}
 private void medio(SaldoEstoque s){if(s.getQuantidadeAtual().signum()==0){s.setCustoMedioAtual(zero6());s.setValorTotalEstoque(zero2());}else s.setCustoMedioAtual(s.getValorTotalEstoque().divide(s.getQuantidadeAtual(),6,RoundingMode.HALF_UP));}private BigDecimal qtd(BigDecimal q,UnidadeMedida u){if(q==null||q.signum()<=0)throw new BusinessException("Quantidade deve ser maior que zero.");if(q.stripTrailingZeros().scale()>3)throw new BusinessException("Quantidade deve ter no máximo três casas decimais.");if(u==UnidadeMedida.UNIDADE&&q.stripTrailingZeros().scale()>0)throw new BusinessException("Quantidade em unidade deve ser inteira.");return q.setScale(3,RoundingMode.UNNECESSARY);}private BigDecimal positivo(BigDecimal v){if(v==null||v.signum()<=0)throw new BusinessException("Valor deve ser maior que zero.");return dinheiro(v);}private BigDecimal dinheiro(BigDecimal v){return(v==null?BigDecimal.ZERO:v).setScale(2,RoundingMode.HALF_UP);}private BigDecimal zero2(){return BigDecimal.ZERO.setScale(2);}private BigDecimal zero6(){return BigDecimal.ZERO.setScale(6);}private String texto(String s){s=limpar(s);return s.isEmpty()?null:s;}private String limpar(String s){return s==null?"":s.trim();}private record Ref(TipoItemEstoque tipo,Long id,Insumo insumo,Produto produto,String nome,UnidadeMedida unidade,Boolean ativo,BigDecimal minimo){}
}
